{
  "name": "opencode-deepseek-balance",
  "version": "1.0.0",
  "description": "Show your DeepSeek account balance in the OpenCode session header, replacing the USD cost",
  "type": "module",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx",
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "scripts": {
    "build": "vite build",
    "typecheck": "tsc -p tsconfig.gui.json"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "deepseek",
    "balance"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.2.2",
    "solid-js": "^1.9.0",
    "typescript": "^5.9.0",
    "vite": "^7.3.0",
    "vite-plugin-solid": "^2.11.0"
  }
}
